BEGIN;

CREATE TABLE "FER_DEPARTAMENTO" (
    "DEP_ID_DEPARTAMENTO" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "DEP_CODIGO" VARCHAR(10) NOT NULL,
    "DEP_NOMBRE" VARCHAR(100) NOT NULL,
    CONSTRAINT "PK_FER_DEPARTAMENTO" PRIMARY KEY ("DEP_ID_DEPARTAMENTO"),
    CONSTRAINT "UK_DEP_CODIGO" UNIQUE ("DEP_CODIGO"),
    CONSTRAINT "UK_DEP_NOMBRE" UNIQUE ("DEP_NOMBRE")
);

CREATE TABLE "FER_MUNICIPIO" (
    "MUN_ID_MUNICIPIO" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "MUN_ID_DEPARTAMENTO" BIGINT NOT NULL,
    "MUN_CODIGO" VARCHAR(10) NOT NULL,
    "MUN_NOMBRE" VARCHAR(100) NOT NULL,
    CONSTRAINT "PK_FER_MUNICIPIO" PRIMARY KEY ("MUN_ID_MUNICIPIO"),
    CONSTRAINT "FK_MUN_DEPARTAMENTO" FOREIGN KEY ("MUN_ID_DEPARTAMENTO")
        REFERENCES "FER_DEPARTAMENTO" ("DEP_ID_DEPARTAMENTO"),
    CONSTRAINT "UK_MUN_CODIGO" UNIQUE ("MUN_ID_DEPARTAMENTO", "MUN_CODIGO"),
    CONSTRAINT "UK_MUN_NOMBRE" UNIQUE ("MUN_ID_DEPARTAMENTO", "MUN_NOMBRE")
);

CREATE TABLE "FER_DIRECCION" (
    "DIR_ID_DIRECCION" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "DIR_ID_MUNICIPIO" BIGINT NOT NULL,
    "DIR_ZONA" VARCHAR(10),
    "DIR_COLONIA" VARCHAR(120),
    "DIR_CALLE" VARCHAR(120),
    "DIR_AVENIDA" VARCHAR(120),
    "DIR_NUMERO_CASA" VARCHAR(30),
    "DIR_REFERENCIA" VARCHAR(300),
    CONSTRAINT "PK_FER_DIRECCION" PRIMARY KEY ("DIR_ID_DIRECCION"),
    CONSTRAINT "FK_DIR_MUNICIPIO" FOREIGN KEY ("DIR_ID_MUNICIPIO")
        REFERENCES "FER_MUNICIPIO" ("MUN_ID_MUNICIPIO")
);

CREATE TABLE "FER_USUARIO" (
    "USU_ID_USUARIO" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "USU_ID_DIRECCION" BIGINT,
    "USU_PRIMER_NOMBRE" VARCHAR(60) NOT NULL,
    "USU_SEGUNDO_NOMBRE" VARCHAR(60),
    "USU_TERCER_NOMBRE" VARCHAR(60),
    "USU_PRIMER_APELLIDO" VARCHAR(60) NOT NULL,
    "USU_SEGUNDO_APELLIDO" VARCHAR(60),
    "USU_NOMBRE_USUARIO" VARCHAR(60) NOT NULL,
    "USU_CORREO" VARCHAR(254) NOT NULL,
    "USU_TELEFONO" VARCHAR(30),
    "USU_CLAVE_HASH" VARCHAR(255) NOT NULL,
    "USU_ESTADO" CHAR(1) NOT NULL DEFAULT 'A',
    "USU_INTENTOS_FALLIDOS" INTEGER NOT NULL DEFAULT 0,
    "USU_FECHA_BLOQUEO" TIMESTAMPTZ,
    "USU_ULTIMO_ACCESO" TIMESTAMPTZ,
    "USU_FECHA_CREACION" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "USU_FECHA_MODIFICACION" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "PK_FER_USUARIO" PRIMARY KEY ("USU_ID_USUARIO"),
    CONSTRAINT "FK_USU_DIRECCION" FOREIGN KEY ("USU_ID_DIRECCION")
        REFERENCES "FER_DIRECCION" ("DIR_ID_DIRECCION"),
    CONSTRAINT "CK_USU_ESTADO" CHECK ("USU_ESTADO" IN ('A', 'I', 'B')),
    CONSTRAINT "CK_USU_INTENTOS" CHECK ("USU_INTENTOS_FALLIDOS" >= 0)
);

CREATE UNIQUE INDEX "UK_USU_NOMBRE_USUARIO"
    ON "FER_USUARIO" (LOWER("USU_NOMBRE_USUARIO"));
CREATE UNIQUE INDEX "UK_USU_CORREO"
    ON "FER_USUARIO" (LOWER("USU_CORREO"));

CREATE TABLE "FER_ROL" (
    "ROL_ID_ROL" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "ROL_NOMBRE" VARCHAR(60) NOT NULL,
    "ROL_DESCRIPCION" VARCHAR(250) NOT NULL,
    "ROL_ESTADO" CHAR(1) NOT NULL DEFAULT 'A',
    CONSTRAINT "PK_FER_ROL" PRIMARY KEY ("ROL_ID_ROL"),
    CONSTRAINT "UK_ROL_NOMBRE" UNIQUE ("ROL_NOMBRE"),
    CONSTRAINT "CK_ROL_ESTADO" CHECK ("ROL_ESTADO" IN ('A', 'I'))
);

CREATE TABLE "FER_PERMISO" (
    "PER_ID_PERMISO" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "PER_CODIGO" VARCHAR(80) NOT NULL,
    "PER_NOMBRE" VARCHAR(100) NOT NULL,
    "PER_MODULO" VARCHAR(60) NOT NULL,
    "PER_ACCION" VARCHAR(60) NOT NULL,
    "PER_DESCRIPCION" VARCHAR(250) NOT NULL,
    "PER_ESTADO" CHAR(1) NOT NULL DEFAULT 'A',
    CONSTRAINT "PK_FER_PERMISO" PRIMARY KEY ("PER_ID_PERMISO"),
    CONSTRAINT "UK_PER_CODIGO" UNIQUE ("PER_CODIGO"),
    CONSTRAINT "UK_PER_MODULO_ACCION" UNIQUE ("PER_MODULO", "PER_ACCION"),
    CONSTRAINT "CK_PER_ESTADO" CHECK ("PER_ESTADO" IN ('A', 'I'))
);

CREATE TABLE "FER_USUARIO_ROL" (
    "URO_ID_USUARIO_ROL" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "URO_ID_USUARIO" BIGINT NOT NULL,
    "URO_ID_ROL" BIGINT NOT NULL,
    "URO_FECHA_ASIGNACION" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "URO_FECHA_REVOCACION" TIMESTAMPTZ,
    "URO_ESTADO" CHAR(1) NOT NULL DEFAULT 'A',
    CONSTRAINT "PK_FER_USUARIO_ROL" PRIMARY KEY ("URO_ID_USUARIO_ROL"),
    CONSTRAINT "FK_URO_USUARIO" FOREIGN KEY ("URO_ID_USUARIO")
        REFERENCES "FER_USUARIO" ("USU_ID_USUARIO"),
    CONSTRAINT "FK_URO_ROL" FOREIGN KEY ("URO_ID_ROL")
        REFERENCES "FER_ROL" ("ROL_ID_ROL"),
    CONSTRAINT "UK_URO_USUARIO_ROL" UNIQUE ("URO_ID_USUARIO", "URO_ID_ROL"),
    CONSTRAINT "CK_URO_ESTADO" CHECK ("URO_ESTADO" IN ('A', 'I')),
    CONSTRAINT "CK_URO_FECHAS" CHECK (
        "URO_FECHA_REVOCACION" IS NULL
        OR "URO_FECHA_REVOCACION" >= "URO_FECHA_ASIGNACION"
    )
);

CREATE TABLE "FER_ROL_PERMISO" (
    "RPE_ID_ROL_PERMISO" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "RPE_ID_ROL" BIGINT NOT NULL,
    "RPE_ID_PERMISO" BIGINT NOT NULL,
    "RPE_FECHA_ASIGNACION" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "RPE_ESTADO" CHAR(1) NOT NULL DEFAULT 'A',
    CONSTRAINT "PK_FER_ROL_PERMISO" PRIMARY KEY ("RPE_ID_ROL_PERMISO"),
    CONSTRAINT "FK_RPE_ROL" FOREIGN KEY ("RPE_ID_ROL")
        REFERENCES "FER_ROL" ("ROL_ID_ROL"),
    CONSTRAINT "FK_RPE_PERMISO" FOREIGN KEY ("RPE_ID_PERMISO")
        REFERENCES "FER_PERMISO" ("PER_ID_PERMISO"),
    CONSTRAINT "UK_RPE_ROL_PERMISO" UNIQUE ("RPE_ID_ROL", "RPE_ID_PERMISO"),
    CONSTRAINT "CK_RPE_ESTADO" CHECK ("RPE_ESTADO" IN ('A', 'I'))
);

CREATE TABLE "FER_CLIENTE" (
    "CLI_ID_CLIENTE" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "CLI_ID_DIRECCION" BIGINT,
    "CLI_TIPO_PERSONA" VARCHAR(10) NOT NULL,
    "CLI_NIT" VARCHAR(20),
    "CLI_PRIMER_NOMBRE" VARCHAR(60),
    "CLI_SEGUNDO_NOMBRE" VARCHAR(60),
    "CLI_TERCER_NOMBRE" VARCHAR(60),
    "CLI_PRIMER_APELLIDO" VARCHAR(60),
    "CLI_SEGUNDO_APELLIDO" VARCHAR(60),
    "CLI_RAZON_SOCIAL" VARCHAR(180),
    "CLI_CORREO" VARCHAR(254),
    "CLI_TELEFONO" VARCHAR(30),
    "CLI_ESTADO" CHAR(1) NOT NULL DEFAULT 'A',
    "CLI_FECHA_CREACION" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "PK_FER_CLIENTE" PRIMARY KEY ("CLI_ID_CLIENTE"),
    CONSTRAINT "FK_CLI_DIRECCION" FOREIGN KEY ("CLI_ID_DIRECCION")
        REFERENCES "FER_DIRECCION" ("DIR_ID_DIRECCION"),
    CONSTRAINT "CK_CLI_TIPO_PERSONA" CHECK (
        "CLI_TIPO_PERSONA" IN ('INDIVIDUAL', 'JURIDICA')
    ),
    CONSTRAINT "CK_CLI_IDENTIFICACION" CHECK (
        (
            "CLI_TIPO_PERSONA" = 'INDIVIDUAL'
            AND "CLI_PRIMER_NOMBRE" IS NOT NULL
            AND "CLI_PRIMER_APELLIDO" IS NOT NULL
        )
        OR (
            "CLI_TIPO_PERSONA" = 'JURIDICA'
            AND "CLI_RAZON_SOCIAL" IS NOT NULL
        )
    ),
    CONSTRAINT "CK_CLI_ESTADO" CHECK ("CLI_ESTADO" IN ('A', 'I'))
);

CREATE TABLE "FER_PROVEEDOR" (
    "PRV_ID_PROVEEDOR" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "PRV_ID_DIRECCION" BIGINT NOT NULL,
    "PRV_NIT" VARCHAR(20) NOT NULL,
    "PRV_RAZON_SOCIAL" VARCHAR(180) NOT NULL,
    "PRV_NOMBRE_CONTACTO" VARCHAR(180),
    "PRV_CORREO" VARCHAR(254) NOT NULL,
    "PRV_TELEFONO" VARCHAR(30) NOT NULL,
    "PRV_ESTADO" CHAR(1) NOT NULL DEFAULT 'A',
    "PRV_FECHA_CREACION" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "PK_FER_PROVEEDOR" PRIMARY KEY ("PRV_ID_PROVEEDOR"),
    CONSTRAINT "FK_PRV_DIRECCION" FOREIGN KEY ("PRV_ID_DIRECCION")
        REFERENCES "FER_DIRECCION" ("DIR_ID_DIRECCION"),
    CONSTRAINT "UK_PRV_NIT" UNIQUE ("PRV_NIT"),
    CONSTRAINT "CK_PRV_ESTADO" CHECK ("PRV_ESTADO" IN ('A', 'I'))
);

CREATE TABLE "FER_CATEGORIA" (
    "CAT_ID_CATEGORIA" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "CAT_NOMBRE" VARCHAR(100) NOT NULL,
    "CAT_DESCRIPCION" VARCHAR(250),
    "CAT_ESTADO" CHAR(1) NOT NULL DEFAULT 'A',
    CONSTRAINT "PK_FER_CATEGORIA" PRIMARY KEY ("CAT_ID_CATEGORIA"),
    CONSTRAINT "UK_CAT_NOMBRE" UNIQUE ("CAT_NOMBRE"),
    CONSTRAINT "CK_CAT_ESTADO" CHECK ("CAT_ESTADO" IN ('A', 'I'))
);

CREATE TABLE "FER_UNIDAD_MEDIDA" (
    "UME_ID_UNIDAD_MEDIDA" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "UME_CODIGO" VARCHAR(20) NOT NULL,
    "UME_NOMBRE" VARCHAR(80) NOT NULL,
    "UME_ABREVIATURA" VARCHAR(15) NOT NULL,
    "UME_ESTADO" CHAR(1) NOT NULL DEFAULT 'A',
    CONSTRAINT "PK_FER_UNIDAD_MEDIDA" PRIMARY KEY ("UME_ID_UNIDAD_MEDIDA"),
    CONSTRAINT "UK_UME_CODIGO" UNIQUE ("UME_CODIGO"),
    CONSTRAINT "UK_UME_NOMBRE" UNIQUE ("UME_NOMBRE"),
    CONSTRAINT "CK_UME_ESTADO" CHECK ("UME_ESTADO" IN ('A', 'I'))
);

CREATE TABLE "FER_PRODUCTO" (
    "PRO_ID_PRODUCTO" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "PRO_ID_CATEGORIA" BIGINT NOT NULL,
    "PRO_ID_UNIDAD_MEDIDA" BIGINT NOT NULL,
    "PRO_CODIGO" VARCHAR(50) NOT NULL,
    "PRO_NOMBRE" VARCHAR(150) NOT NULL,
    "PRO_DESCRIPCION" VARCHAR(500),
    "PRO_IMAGEN" VARCHAR(300),
    "PRO_PRECIO_COMPRA" NUMERIC(14,2) NOT NULL DEFAULT 0,
    "PRO_PRECIO_VENTA" NUMERIC(14,2) NOT NULL,
    "PRO_PORCENTAJE_IMPUESTO" NUMERIC(5,2) NOT NULL DEFAULT 0,
    "PRO_EXISTENCIA_MINIMA" NUMERIC(14,3) NOT NULL DEFAULT 0,
    "PRO_ESTADO" CHAR(1) NOT NULL DEFAULT 'A',
    "PRO_FECHA_CREACION" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "PRO_FECHA_MODIFICACION" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "PK_FER_PRODUCTO" PRIMARY KEY ("PRO_ID_PRODUCTO"),
    CONSTRAINT "FK_PRO_CATEGORIA" FOREIGN KEY ("PRO_ID_CATEGORIA")
        REFERENCES "FER_CATEGORIA" ("CAT_ID_CATEGORIA"),
    CONSTRAINT "FK_PRO_UNIDAD_MEDIDA" FOREIGN KEY ("PRO_ID_UNIDAD_MEDIDA")
        REFERENCES "FER_UNIDAD_MEDIDA" ("UME_ID_UNIDAD_MEDIDA"),
    CONSTRAINT "UK_PRO_CODIGO" UNIQUE ("PRO_CODIGO"),
    CONSTRAINT "CK_PRO_PRECIOS" CHECK (
        "PRO_PRECIO_COMPRA" >= 0 AND "PRO_PRECIO_VENTA" >= 0
    ),
    CONSTRAINT "CK_PRO_IMPUESTO" CHECK (
        "PRO_PORCENTAJE_IMPUESTO" BETWEEN 0 AND 100
    ),
    CONSTRAINT "CK_PRO_EXISTENCIA_MINIMA" CHECK ("PRO_EXISTENCIA_MINIMA" >= 0),
    CONSTRAINT "CK_PRO_ESTADO" CHECK ("PRO_ESTADO" IN ('A', 'I'))
);

CREATE TABLE "FER_COMPRA" (
    "COM_ID_COMPRA" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "COM_ID_PROVEEDOR" BIGINT NOT NULL,
    "COM_NUMERO_COMPRA" VARCHAR(40) NOT NULL,
    "COM_FECHA_COMPRA" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "COM_FECHA_ESPERADA" DATE,
    "COM_ESTADO" VARCHAR(20) NOT NULL DEFAULT 'CREADA',
    "COM_OBSERVACION" VARCHAR(500),
    CONSTRAINT "PK_FER_COMPRA" PRIMARY KEY ("COM_ID_COMPRA"),
    CONSTRAINT "FK_COM_PROVEEDOR" FOREIGN KEY ("COM_ID_PROVEEDOR")
        REFERENCES "FER_PROVEEDOR" ("PRV_ID_PROVEEDOR"),
    CONSTRAINT "UK_COM_NUMERO" UNIQUE ("COM_NUMERO_COMPRA"),
    CONSTRAINT "CK_COM_ESTADO" CHECK (
        "COM_ESTADO" IN ('CREADA', 'ENVIADA', 'PARCIAL', 'RECIBIDA', 'CANCELADA')
    )
);

CREATE TABLE "FER_DETALLE_COMPRA" (
    "DCO_ID_DETALLE_COMPRA" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "DCO_ID_COMPRA" BIGINT NOT NULL,
    "DCO_ID_PRODUCTO" BIGINT NOT NULL,
    "DCO_CANTIDAD" NUMERIC(14,3) NOT NULL,
    "DCO_COSTO_UNITARIO" NUMERIC(14,2) NOT NULL,
    "DCO_PORCENTAJE_DESCUENTO" NUMERIC(5,2) NOT NULL DEFAULT 0,
    "DCO_PORCENTAJE_IMPUESTO" NUMERIC(5,2) NOT NULL DEFAULT 0,
    CONSTRAINT "PK_FER_DETALLE_COMPRA" PRIMARY KEY ("DCO_ID_DETALLE_COMPRA"),
    CONSTRAINT "FK_DCO_COMPRA" FOREIGN KEY ("DCO_ID_COMPRA")
        REFERENCES "FER_COMPRA" ("COM_ID_COMPRA"),
    CONSTRAINT "FK_DCO_PRODUCTO" FOREIGN KEY ("DCO_ID_PRODUCTO")
        REFERENCES "FER_PRODUCTO" ("PRO_ID_PRODUCTO"),
    CONSTRAINT "UK_DCO_COMPRA_PRODUCTO" UNIQUE ("DCO_ID_COMPRA", "DCO_ID_PRODUCTO"),
    CONSTRAINT "CK_DCO_CANTIDAD" CHECK ("DCO_CANTIDAD" > 0),
    CONSTRAINT "CK_DCO_COSTO" CHECK ("DCO_COSTO_UNITARIO" >= 0),
    CONSTRAINT "CK_DCO_DESCUENTO" CHECK (
        "DCO_PORCENTAJE_DESCUENTO" BETWEEN 0 AND 100
    ),
    CONSTRAINT "CK_DCO_IMPUESTO" CHECK (
        "DCO_PORCENTAJE_IMPUESTO" BETWEEN 0 AND 100
    )
);

CREATE TABLE "FER_RECEPCION" (
    "REC_ID_RECEPCION" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "REC_ID_COMPRA" BIGINT NOT NULL,
    "REC_NUMERO_RECEPCION" VARCHAR(40) NOT NULL,
    "REC_FECHA_RECEPCION" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "REC_ESTADO" VARCHAR(20) NOT NULL DEFAULT 'BORRADOR',
    "REC_OBSERVACION" VARCHAR(500),
    CONSTRAINT "PK_FER_RECEPCION" PRIMARY KEY ("REC_ID_RECEPCION"),
    CONSTRAINT "FK_REC_COMPRA" FOREIGN KEY ("REC_ID_COMPRA")
        REFERENCES "FER_COMPRA" ("COM_ID_COMPRA"),
    CONSTRAINT "UK_REC_NUMERO" UNIQUE ("REC_NUMERO_RECEPCION"),
    CONSTRAINT "CK_REC_ESTADO" CHECK (
        "REC_ESTADO" IN ('BORRADOR', 'CONFIRMADA', 'CANCELADA')
    )
);

CREATE TABLE "FER_DETALLE_RECEPCION" (
    "DRE_ID_DETALLE_RECEPCION" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "DRE_ID_RECEPCION" BIGINT NOT NULL,
    "DRE_ID_DETALLE_COMPRA" BIGINT NOT NULL,
    "DRE_CANTIDAD_RECIBIDA" NUMERIC(14,3) NOT NULL DEFAULT 0,
    "DRE_CANTIDAD_RECHAZADA" NUMERIC(14,3) NOT NULL DEFAULT 0,
    "DRE_MOTIVO_RECHAZO" VARCHAR(300),
    CONSTRAINT "PK_FER_DETALLE_RECEPCION" PRIMARY KEY ("DRE_ID_DETALLE_RECEPCION"),
    CONSTRAINT "FK_DRE_RECEPCION" FOREIGN KEY ("DRE_ID_RECEPCION")
        REFERENCES "FER_RECEPCION" ("REC_ID_RECEPCION"),
    CONSTRAINT "FK_DRE_DETALLE_COMPRA" FOREIGN KEY ("DRE_ID_DETALLE_COMPRA")
        REFERENCES "FER_DETALLE_COMPRA" ("DCO_ID_DETALLE_COMPRA"),
    CONSTRAINT "UK_DRE_RECEPCION_DETALLE" UNIQUE (
        "DRE_ID_RECEPCION", "DRE_ID_DETALLE_COMPRA"
    ),
    CONSTRAINT "CK_DRE_CANTIDADES" CHECK (
        "DRE_CANTIDAD_RECIBIDA" >= 0
        AND "DRE_CANTIDAD_RECHAZADA" >= 0
        AND ("DRE_CANTIDAD_RECIBIDA" + "DRE_CANTIDAD_RECHAZADA") > 0
    ),
    CONSTRAINT "CK_DRE_MOTIVO" CHECK (
        "DRE_CANTIDAD_RECHAZADA" = 0 OR "DRE_MOTIVO_RECHAZO" IS NOT NULL
    )
);

CREATE TABLE "FER_INVENTARIO" (
    "INV_ID_INVENTARIO" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "INV_ID_PRODUCTO" BIGINT NOT NULL,
    "INV_EXISTENCIA_ACTUAL" NUMERIC(14,3) NOT NULL DEFAULT 0,
    "INV_CANTIDAD_RESERVADA" NUMERIC(14,3) NOT NULL DEFAULT 0,
    "INV_FECHA_ULTIMO_MOVIMIENTO" TIMESTAMPTZ,
    "INV_VERSION" INTEGER NOT NULL DEFAULT 0,
    CONSTRAINT "PK_FER_INVENTARIO" PRIMARY KEY ("INV_ID_INVENTARIO"),
    CONSTRAINT "FK_INV_PRODUCTO" FOREIGN KEY ("INV_ID_PRODUCTO")
        REFERENCES "FER_PRODUCTO" ("PRO_ID_PRODUCTO"),
    CONSTRAINT "UK_INV_PRODUCTO" UNIQUE ("INV_ID_PRODUCTO"),
    CONSTRAINT "CK_INV_EXISTENCIAS" CHECK (
        "INV_EXISTENCIA_ACTUAL" >= 0
        AND "INV_CANTIDAD_RESERVADA" >= 0
        AND "INV_CANTIDAD_RESERVADA" <= "INV_EXISTENCIA_ACTUAL"
    ),
    CONSTRAINT "CK_INV_VERSION" CHECK ("INV_VERSION" >= 0)
);

CREATE TABLE "FER_MOVIMIENTO_INVENTARIO" (
    "MOV_ID_MOVIMIENTO" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "MOV_ID_INVENTARIO" BIGINT NOT NULL,
    "MOV_ID_USUARIO" BIGINT NOT NULL,
    "MOV_TIPO_MOVIMIENTO" VARCHAR(15) NOT NULL,
    "MOV_CANTIDAD" NUMERIC(14,3) NOT NULL,
    "MOV_EXISTENCIA_ANTERIOR" NUMERIC(14,3) NOT NULL,
    "MOV_EXISTENCIA_NUEVA" NUMERIC(14,3) NOT NULL,
    "MOV_FECHA_MOVIMIENTO" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "MOV_MODULO_ORIGEN" VARCHAR(40) NOT NULL,
    "MOV_ID_REGISTRO_ORIGEN" BIGINT NOT NULL,
    "MOV_NUMERO_DOCUMENTO" VARCHAR(40),
    "MOV_MOTIVO" VARCHAR(300),
    CONSTRAINT "PK_FER_MOVIMIENTO" PRIMARY KEY ("MOV_ID_MOVIMIENTO"),
    CONSTRAINT "FK_MOV_INVENTARIO" FOREIGN KEY ("MOV_ID_INVENTARIO")
        REFERENCES "FER_INVENTARIO" ("INV_ID_INVENTARIO"),
    CONSTRAINT "FK_MOV_USUARIO" FOREIGN KEY ("MOV_ID_USUARIO")
        REFERENCES "FER_USUARIO" ("USU_ID_USUARIO"),
    CONSTRAINT "CK_MOV_TIPO" CHECK (
        "MOV_TIPO_MOVIMIENTO" IN ('ENTRADA', 'SALIDA', 'AJUSTE', 'DEVOLUCION')
    ),
    CONSTRAINT "CK_MOV_CANTIDAD" CHECK ("MOV_CANTIDAD" > 0),
    CONSTRAINT "CK_MOV_EXISTENCIAS" CHECK (
        "MOV_EXISTENCIA_ANTERIOR" >= 0 AND "MOV_EXISTENCIA_NUEVA" >= 0
    )
);

CREATE TABLE "FER_ALERTA_INVENTARIO" (
    "ALE_ID_ALERTA" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "ALE_ID_MOVIMIENTO" BIGINT NOT NULL,
    "ALE_ID_USUARIO_ATIENDE" BIGINT,
    "ALE_TIPO_ALERTA" VARCHAR(30) NOT NULL,
    "ALE_MENSAJE" VARCHAR(300) NOT NULL,
    "ALE_EXISTENCIA_MINIMA" NUMERIC(14,3) NOT NULL,
    "ALE_FECHA_GENERACION" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "ALE_FECHA_ATENCION" TIMESTAMPTZ,
    "ALE_ESTADO" VARCHAR(15) NOT NULL DEFAULT 'PENDIENTE',
    CONSTRAINT "PK_FER_ALERTA" PRIMARY KEY ("ALE_ID_ALERTA"),
    CONSTRAINT "FK_ALE_MOVIMIENTO" FOREIGN KEY ("ALE_ID_MOVIMIENTO")
        REFERENCES "FER_MOVIMIENTO_INVENTARIO" ("MOV_ID_MOVIMIENTO"),
    CONSTRAINT "FK_ALE_USUARIO" FOREIGN KEY ("ALE_ID_USUARIO_ATIENDE")
        REFERENCES "FER_USUARIO" ("USU_ID_USUARIO"),
    CONSTRAINT "CK_ALE_MINIMO" CHECK ("ALE_EXISTENCIA_MINIMA" >= 0),
    CONSTRAINT "CK_ALE_ESTADO" CHECK (
        "ALE_ESTADO" IN ('PENDIENTE', 'ATENDIDA', 'DESCARTADA')
    ),
    CONSTRAINT "CK_ALE_ATENCION" CHECK (
        ("ALE_ESTADO" = 'PENDIENTE' AND "ALE_FECHA_ATENCION" IS NULL)
        OR "ALE_ESTADO" IN ('ATENDIDA', 'DESCARTADA')
    )
);

CREATE TABLE "FER_ESTADO_PEDIDO" (
    "EPE_ID_ESTADO_PEDIDO" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "EPE_CODIGO" VARCHAR(30) NOT NULL,
    "EPE_NOMBRE" VARCHAR(80) NOT NULL,
    "EPE_ORDEN" INTEGER NOT NULL,
    "EPE_PERMITE_MODIFICAR" BOOLEAN NOT NULL DEFAULT FALSE,
    "EPE_PERMITE_FACTURAR" BOOLEAN NOT NULL DEFAULT FALSE,
    "EPE_ESTADO" CHAR(1) NOT NULL DEFAULT 'A',
    CONSTRAINT "PK_FER_ESTADO_PEDIDO" PRIMARY KEY ("EPE_ID_ESTADO_PEDIDO"),
    CONSTRAINT "UK_EPE_CODIGO" UNIQUE ("EPE_CODIGO"),
    CONSTRAINT "UK_EPE_ORDEN" UNIQUE ("EPE_ORDEN"),
    CONSTRAINT "CK_EPE_ORDEN" CHECK ("EPE_ORDEN" > 0),
    CONSTRAINT "CK_EPE_ESTADO" CHECK ("EPE_ESTADO" IN ('A', 'I'))
);

CREATE TABLE "FER_DESCUENTO" (
    "DES_ID_DESCUENTO" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "DES_NOMBRE" VARCHAR(100) NOT NULL,
    "DES_TIPO" VARCHAR(15) NOT NULL,
    "DES_VALOR" NUMERIC(14,2) NOT NULL,
    "DES_REQUIERE_APROBACION" BOOLEAN NOT NULL DEFAULT FALSE,
    "DES_FECHA_INICIO" TIMESTAMPTZ NOT NULL,
    "DES_FECHA_FIN" TIMESTAMPTZ NOT NULL,
    "DES_ESTADO" CHAR(1) NOT NULL DEFAULT 'A',
    CONSTRAINT "PK_FER_DESCUENTO" PRIMARY KEY ("DES_ID_DESCUENTO"),
    CONSTRAINT "CK_DES_TIPO" CHECK ("DES_TIPO" IN ('PORCENTAJE', 'MONTO')),
    CONSTRAINT "CK_DES_VALOR" CHECK (
        "DES_VALOR" >= 0
        AND ("DES_TIPO" <> 'PORCENTAJE' OR "DES_VALOR" <= 100)
    ),
    CONSTRAINT "CK_DES_FECHAS" CHECK ("DES_FECHA_FIN" >= "DES_FECHA_INICIO"),
    CONSTRAINT "CK_DES_ESTADO" CHECK ("DES_ESTADO" IN ('A', 'I'))
);

CREATE TABLE "FER_PEDIDO" (
    "PED_ID_PEDIDO" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "PED_ID_CLIENTE" BIGINT NOT NULL,
    "PED_ID_ESTADO_PEDIDO" BIGINT NOT NULL,
    "PED_ID_DESCUENTO" BIGINT,
    "PED_NUMERO_PEDIDO" VARCHAR(40) NOT NULL,
    "PED_FECHA_PEDIDO" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "PED_FECHA_REQUERIDA" DATE,
    "PED_PORCENTAJE_DESCUENTO" NUMERIC(5,2) NOT NULL DEFAULT 0,
    "PED_OBSERVACION" VARCHAR(500),
    CONSTRAINT "PK_FER_PEDIDO" PRIMARY KEY ("PED_ID_PEDIDO"),
    CONSTRAINT "FK_PED_CLIENTE" FOREIGN KEY ("PED_ID_CLIENTE")
        REFERENCES "FER_CLIENTE" ("CLI_ID_CLIENTE"),
    CONSTRAINT "FK_PED_ESTADO" FOREIGN KEY ("PED_ID_ESTADO_PEDIDO")
        REFERENCES "FER_ESTADO_PEDIDO" ("EPE_ID_ESTADO_PEDIDO"),
    CONSTRAINT "FK_PED_DESCUENTO" FOREIGN KEY ("PED_ID_DESCUENTO")
        REFERENCES "FER_DESCUENTO" ("DES_ID_DESCUENTO"),
    CONSTRAINT "UK_PED_NUMERO" UNIQUE ("PED_NUMERO_PEDIDO"),
    CONSTRAINT "CK_PED_DESCUENTO" CHECK (
        "PED_PORCENTAJE_DESCUENTO" BETWEEN 0 AND 100
    )
);

CREATE TABLE "FER_DETALLE_PEDIDO" (
    "DPE_ID_DETALLE_PEDIDO" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "DPE_ID_PEDIDO" BIGINT NOT NULL,
    "DPE_ID_PRODUCTO" BIGINT NOT NULL,
    "DPE_CANTIDAD" NUMERIC(14,3) NOT NULL,
    "DPE_PRECIO_UNITARIO" NUMERIC(14,2) NOT NULL,
    "DPE_PORCENTAJE_DESCUENTO" NUMERIC(5,2) NOT NULL DEFAULT 0,
    "DPE_PORCENTAJE_IMPUESTO" NUMERIC(5,2) NOT NULL DEFAULT 0,
    CONSTRAINT "PK_FER_DETALLE_PEDIDO" PRIMARY KEY ("DPE_ID_DETALLE_PEDIDO"),
    CONSTRAINT "FK_DPE_PEDIDO" FOREIGN KEY ("DPE_ID_PEDIDO")
        REFERENCES "FER_PEDIDO" ("PED_ID_PEDIDO"),
    CONSTRAINT "FK_DPE_PRODUCTO" FOREIGN KEY ("DPE_ID_PRODUCTO")
        REFERENCES "FER_PRODUCTO" ("PRO_ID_PRODUCTO"),
    CONSTRAINT "UK_DPE_PEDIDO_PRODUCTO" UNIQUE ("DPE_ID_PEDIDO", "DPE_ID_PRODUCTO"),
    CONSTRAINT "CK_DPE_CANTIDAD" CHECK ("DPE_CANTIDAD" > 0),
    CONSTRAINT "CK_DPE_PRECIO" CHECK ("DPE_PRECIO_UNITARIO" >= 0),
    CONSTRAINT "CK_DPE_DESCUENTO" CHECK (
        "DPE_PORCENTAJE_DESCUENTO" BETWEEN 0 AND 100
    ),
    CONSTRAINT "CK_DPE_IMPUESTO" CHECK (
        "DPE_PORCENTAJE_IMPUESTO" BETWEEN 0 AND 100
    )
);

CREATE TABLE "FER_HISTORIAL_PEDIDO" (
    "HPE_ID_HISTORIAL_PEDIDO" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "HPE_ID_PEDIDO" BIGINT NOT NULL,
    "HPE_ID_ESTADO_ANTERIOR" BIGINT,
    "HPE_ID_ESTADO_NUEVO" BIGINT NOT NULL,
    "HPE_ID_USUARIO" BIGINT NOT NULL,
    "HPE_FECHA_CAMBIO" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "HPE_OBSERVACION" VARCHAR(500),
    CONSTRAINT "PK_FER_HISTORIAL_PEDIDO" PRIMARY KEY ("HPE_ID_HISTORIAL_PEDIDO"),
    CONSTRAINT "FK_HPE_PEDIDO" FOREIGN KEY ("HPE_ID_PEDIDO")
        REFERENCES "FER_PEDIDO" ("PED_ID_PEDIDO"),
    CONSTRAINT "FK_HPE_ESTADO_ANTERIOR" FOREIGN KEY ("HPE_ID_ESTADO_ANTERIOR")
        REFERENCES "FER_ESTADO_PEDIDO" ("EPE_ID_ESTADO_PEDIDO"),
    CONSTRAINT "FK_HPE_ESTADO_NUEVO" FOREIGN KEY ("HPE_ID_ESTADO_NUEVO")
        REFERENCES "FER_ESTADO_PEDIDO" ("EPE_ID_ESTADO_PEDIDO"),
    CONSTRAINT "FK_HPE_USUARIO" FOREIGN KEY ("HPE_ID_USUARIO")
        REFERENCES "FER_USUARIO" ("USU_ID_USUARIO"),
    CONSTRAINT "CK_HPE_CAMBIO" CHECK (
        "HPE_ID_ESTADO_ANTERIOR" IS NULL
        OR "HPE_ID_ESTADO_ANTERIOR" <> "HPE_ID_ESTADO_NUEVO"
    )
);

CREATE TABLE "FER_APROBACION" (
    "APR_ID_APROBACION" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "APR_ID_PEDIDO" BIGINT NOT NULL,
    "APR_ID_USUARIO_SOLICITA" BIGINT NOT NULL,
    "APR_ID_USUARIO_AUTORIZA" BIGINT,
    "APR_TIPO_APROBACION" VARCHAR(30) NOT NULL,
    "APR_VALOR_SOLICITADO" NUMERIC(14,2) NOT NULL,
    "APR_VALOR_PERMITIDO" NUMERIC(14,2) NOT NULL,
    "APR_ESTADO" VARCHAR(15) NOT NULL DEFAULT 'PENDIENTE',
    "APR_FECHA_SOLICITUD" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "APR_FECHA_RESPUESTA" TIMESTAMPTZ,
    "APR_OBSERVACION" VARCHAR(500),
    CONSTRAINT "PK_FER_APROBACION" PRIMARY KEY ("APR_ID_APROBACION"),
    CONSTRAINT "FK_APR_PEDIDO" FOREIGN KEY ("APR_ID_PEDIDO")
        REFERENCES "FER_PEDIDO" ("PED_ID_PEDIDO"),
    CONSTRAINT "FK_APR_USUARIO_SOLICITA" FOREIGN KEY ("APR_ID_USUARIO_SOLICITA")
        REFERENCES "FER_USUARIO" ("USU_ID_USUARIO"),
    CONSTRAINT "FK_APR_USUARIO_AUTORIZA" FOREIGN KEY ("APR_ID_USUARIO_AUTORIZA")
        REFERENCES "FER_USUARIO" ("USU_ID_USUARIO"),
    CONSTRAINT "CK_APR_VALORES" CHECK (
        "APR_VALOR_SOLICITADO" >= 0 AND "APR_VALOR_PERMITIDO" >= 0
    ),
    CONSTRAINT "CK_APR_ESTADO" CHECK (
        "APR_ESTADO" IN ('PENDIENTE', 'APROBADA', 'RECHAZADA')
    ),
    CONSTRAINT "CK_APR_RESPUESTA" CHECK (
        (
            "APR_ESTADO" = 'PENDIENTE'
            AND "APR_ID_USUARIO_AUTORIZA" IS NULL
            AND "APR_FECHA_RESPUESTA" IS NULL
        )
        OR (
            "APR_ESTADO" IN ('APROBADA', 'RECHAZADA')
            AND "APR_ID_USUARIO_AUTORIZA" IS NOT NULL
            AND "APR_FECHA_RESPUESTA" IS NOT NULL
        )
    )
);

CREATE TABLE "FER_VENTA" (
    "VEN_ID_VENTA" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "VEN_ID_PEDIDO" BIGINT NOT NULL,
