CREATE OR REPLACE FUNCTION "FER_FN_VALIDAR_DETALLE_RECEPCION"()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
    V_COMPRA_RECEPCION BIGINT;
    V_COMPRA_DETALLE BIGINT;
BEGIN
    SELECT "REC_ID_COMPRA"
      INTO STRICT V_COMPRA_RECEPCION
      FROM "FER_RECEPCION"
     WHERE "REC_ID_RECEPCION" = NEW."DRE_ID_RECEPCION";

    SELECT "DCO_ID_COMPRA"
      INTO STRICT V_COMPRA_DETALLE
      FROM "FER_DETALLE_COMPRA"
     WHERE "DCO_ID_DETALLE_COMPRA" = NEW."DRE_ID_DETALLE_COMPRA";

    IF V_COMPRA_RECEPCION IS DISTINCT FROM V_COMPRA_DETALLE THEN
        RAISE EXCEPTION
            'El detalle de compra no pertenece a la compra de la recepción';
    END IF;

    RETURN NEW;
END;
$$;

CREATE TRIGGER "TR_DRE_VALIDAR_COMPRA"
BEFORE INSERT OR UPDATE OF "DRE_ID_RECEPCION", "DRE_ID_DETALLE_COMPRA"
ON "FER_DETALLE_RECEPCION"
FOR EACH ROW
EXECUTE FUNCTION "FER_FN_VALIDAR_DETALLE_RECEPCION"();

CREATE OR REPLACE FUNCTION "FER_FN_VALIDAR_DETALLE_VENTA"()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
    V_PEDIDO_VENTA BIGINT;
    V_PEDIDO_DETALLE BIGINT;
BEGIN
    SELECT "VEN_ID_PEDIDO"
      INTO STRICT V_PEDIDO_VENTA
      FROM "FER_VENTA"
     WHERE "VEN_ID_VENTA" = NEW."DVE_ID_VENTA";

    SELECT "DPE_ID_PEDIDO"
      INTO STRICT V_PEDIDO_DETALLE
      FROM "FER_DETALLE_PEDIDO"
     WHERE "DPE_ID_DETALLE_PEDIDO" = NEW."DVE_ID_DETALLE_PEDIDO";

    IF V_PEDIDO_VENTA IS DISTINCT FROM V_PEDIDO_DETALLE THEN
        RAISE EXCEPTION
            'El detalle vendido no pertenece al pedido relacionado con la venta';
    END IF;

    RETURN NEW;
END;
$$;

CREATE TRIGGER "TR_DVE_VALIDAR_PEDIDO"
BEFORE INSERT OR UPDATE OF "DVE_ID_VENTA", "DVE_ID_DETALLE_PEDIDO"
ON "FER_DETALLE_VENTA"
FOR EACH ROW
EXECUTE FUNCTION "FER_FN_VALIDAR_DETALLE_VENTA"();

CREATE OR REPLACE FUNCTION "FER_FN_VALIDAR_REFERENCIA_PAGO"()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
    V_REQUIERE_REFERENCIA BOOLEAN;
BEGIN
    SELECT "MPA_REQUIERE_REFERENCIA"
      INTO STRICT V_REQUIERE_REFERENCIA
      FROM "FER_METODO_PAGO"
     WHERE "MPA_ID_METODO_PAGO" = NEW."PAG_ID_METODO_PAGO";

    IF V_REQUIERE_REFERENCIA
       AND NULLIF(BTRIM(NEW."PAG_REFERENCIA"), '') IS NULL THEN
        RAISE EXCEPTION 'El método de pago requiere una referencia';
    END IF;

    RETURN NEW;
END;
$$;

CREATE TRIGGER "TR_PAG_VALIDAR_REFERENCIA"
BEFORE INSERT OR UPDATE OF "PAG_ID_METODO_PAGO", "PAG_REFERENCIA"
ON "FER_PAGO"
FOR EACH ROW
EXECUTE FUNCTION "FER_FN_VALIDAR_REFERENCIA_PAGO"();

